public T addHeader(CharSequence name, Object value) {
    if (value == null) {
      LOGGER.warn("Value was null, set to \"\"");
      value = "";
    }

    this.headers.add(name, value);
    return asDerivedType();
  }

public T addHeader(CharSequence name, Iterable<?> values) {
