public Map<String, HostStats> getStatsPerHost() {
    return statsPerHost;
  }

public long getTotalConnectionCount() {
    return statsPerHost
            .values()
            .stream()
            .mapToLong(HostStats::getHostConnectionCount)
            .sum();
  }

docstring:
